-- 019_refresh_standard_forms.sql
--
-- Brings every keyed standard template back in line with
-- src/config/standardForms.js.
--
-- The earlier migrations each carried one form, so a change made to a shared
-- field reached only the form whose migration was regenerated: the season line
-- moved from the season record to the Umm al-Qura calendar, and the readiness
-- minutes took it while «تعهد مقدم خدمات الإعاشة» went on printing the season's
-- own name — ١٤٤٦هـ — because nothing had rewritten it since.
--
-- This one carries all 10 of them, which is the only way the file and the
-- table stay honest about each other.
--
-- Templates the customer authored have no key and are never touched by this —
-- including copies made from a standard form. A copy is a fork: it keeps the
-- text it was made from, and refreshing the original does not reach it.

INSERT INTO public.form_templates
  (key, title, description, category, definition,
   requires_signature, requires_attachment, is_standard, active, updated_at)
VALUES
  ('caterer_pledge', 'تعهد مقدم خدمات الإعاشة', 'إقرار المتعهد باطلاعه على كراسة ملحق العقد والتزامه بالاشتراطات التشغيلية والرقابية للموسم.', 'تعاقدي',
   '{"blocks":[{"id":"p1","type":"heading","text":"تعهد مقدم خدمات الإعاشة لموسم حج {{hijri_year}}هـ"},{"id":"p2","type":"paragraph","text":"يقر المتعهد / {{caterer_name}} المتعاقد بموجب العقد رقم ({{contract_number}}) بالاطلاع على كراسة ملحق العقد التي تتضمن الاشتراطات والمواصفات الفنية، والتي تم إرسالها إليه إلكترونيًا من قبل شركة {{company_name}}، ويتعهد بالالتزام التام بجميع ما ورد فيها والعمل بموجبها."},{"id":"p3","type":"paragraph","text":"ويقر بالتعهد والالتزام بالتالي:"},{"id":"p4","type":"list","ordered":false,"items":["التعهد والالتزام بتقديم الخطة التشغيلية لتنفيذ نطاق الأعمال المطلوبة، بموعد أقصاه {{plan_due_date}}.","التعهد والالتزام بكافة التعليمات والاشتراطات الصادرة من الجهات الحكومية والرقابية، ومنها (وزارة الحج والعمرة - المديرية العامة للدفاع المدني - هيئة الغذاء والدواء - أمانة العاصمة المقدسة - شركة كدانة للتنمية والتطوير)، وجميع التزامات الجهات الرقابية المشاركة في أعمال الموسم.","التعهد والالتزام بتوفير جميع الاشتراطات والمتطلبات الخاصة بالعاملين والكادر البشري، واستخراج التصاريح اللازمة لهم حسب أنظمة الجهات الرقابية ذات العلاقة، مع توفير الزي الموحد لهم بشعار المنشأة.","التعهد والالتزام بالإفصاح عن مصدر التوريد والتموين (محلية - مستوردة) للمواد المستخدمة في التحضير، مثل: (اللحوم - الأسماك - الدواجن - منتجات الحليب والألبان - البيض …) وأنواعها (مجمد - مبرد).","التعهد والالتزام بأهمية التأكد من صلاحية جميع المواد الغذائية وتخزينها بالشكل الصحيح، والتحقق من مدى مطابقتها لمتطلبات اللوائح الفنية والمواصفات الغذائية المعتمدة، وتوفير معلومات صحيحة وغير مضللة.","التعهد والالتزام بالمحافظة على النظافة وجودة وصحة الأطعمة المقدمة للحجاج والزوار، ويتحمل كامل المسؤولية في حالة وجود أي أضرار على الصحة العامة للحجاج والزوار تكون سببها تلك الأطعمة، على سبيل المثال: التسمم الغذائي لا سمح الله.","التعهد والالتزام بسحب العينات المرجعية وعدم إتلافها طيلة أيام عمل الموسم حتى انتهائه، ونقلها من المشاعر المقدسة إلى المطبخ الرئيسي، حيث يتم إتلاف العينات بعد انتهاء الموسم بعد أخذ موافقة من إدارة قطاع التغذية بالإتلاف، ويتم توثيق عملية الإتلاف عن طريق محضر وإرساله إلى إدارة قطاع التغذية بشركة {{company_name}}.","التعهد والالتزام بحصوله على دورة تأهيل وتدريب الطهاة على استخدام الكيروسين بعدد (10) ساعات تدريبية، وبحد أدنى متدرب واحد لكل مطبخ، على أن يتم تسليم شهادات التدريب إلى إدارة قطاع التغذية بشركة {{company_name}} في موعد أقصاه {{training_due_date}}.","التعهد والالتزام بسداد كافة التكاليف الناتجة عن سوء تنفيذ مهامه، وكذلك التكاليف الناتجة عن تصرفات عمالته داخل المخيمات سواء في المطبخ أو المرافق، وذلك في مشعري (عرفات - منى).","التعهد والالتزام بسداد قيمة الوقود (الكيروسين) لتشغيل عملية الطبخ داخل المشاعر.","التعهد والالتزام بسداد قيمة استهلاك الكهرباء داخل مشعري (عرفات - منى).","التعهد والالتزام بتوفير اللوحة النموذجية بمواقع الطبخ في المشاعر المقدسة (عرفة - منى) طيلة فترة الموسم، وتحتوي على:"]},{"id":"p5","type":"list","ordered":true,"items":["قائمة الطعام (المنيو) وموضحة أوقات توزيع الوجبات، باللغة العربية ولغة الحاج.","قائمة مسببات الحساسية، باللغة العربية ولغة الحاج.","قائمة السعرات الحرارية، باللغة العربية ولغة الحاج.","استبيان رضا الحاج والشكاوى والاقتراحات، باللغة العربية ولغة الحاج.","السجل التجاري للمنشأة.","رخصة البلدية وتأهيل متعهد الحج.","ملصقات إرشادية وتوعوية، باللغة العربية ولغة الحاج.","البطاقات الصحية للعاملين."]},{"id":"p6","type":"list","ordered":false,"items":["التعهد والالتزام بتوفير ملصق (غلاف) لجميع الوجبات الغذائية كما تم توضيح تفاصيله في كراسة ملحق العقد.","التعهد والالتزام بتوفير عربات لنقل وتوزيع الوجبات داخل المخيمات بكميات كافية ذات (الأربع عجلات).","التعهد والالتزام بتوفير مركبة وسيلة نقل مغلقة، ويتم وضع ملصق على المركبة بها شعار واسم المنشأة، مع ضرورة توفير تصريح دخول المركبة للمشاعر المقدسة.","التعهد والالتزام بتوفير أجهزة مستشعرات الحرارة (Data Logger) داخل مركبات النقل.","التعهد والالتزام بتوفير أجهزة تتبع داخل مركبات النقل.","التعهد والالتزام بتوفير عربات كافية لا تقل عن ٤ عربات ذات (الأربع عجلات)، وتكون مغلقة لاستخدامها في سلاسل الإمداد.","التعهد والالتزام بأنه اطلع على كامل لائحة العقوبات والغرامات، ويتعهد بالالتزام بدفع الغرامات على أي مخالفة وردت في اللائحة في حال رصدها من قبل إدارة قطاع التغذية في شركة {{company_name}}.","التعهد والالتزام بأنه تم الاطلاع على كامل الشروط والمواصفات والالتزامات والاشتراطات والشروط الجزائية في العقد وكراسة ملحق العقد، وأتعهد بالالتزام بها وبجميع ما ورد فيها، بالإضافة إلى جميع التعاميم الإلحاقية الصادرة من إدارة قطاع التغذية في شركة {{company_name}}، مع تحملي كافة الإجراءات أو الغرامات المترتبة على إخلالي بها.","التعهد والالتزام بالتعاون مع شركة {{company_name}} في كافة الإجراءات المتعلقة بخدمات التغذية وأوقات تسليم الوجبات الغذائية للحجاج على وجه الخصوص.","التعهد والالتزام بالتنسيق مع شركة {{company_name}} وفق النطاق المكاني لمعالجة أي نقص أو خلل في تنفيذ المتعهد لالتزاماته التعاقدية.","التعهد والالتزام بوضع QR-CODE مخصص لاستبيان رضا الحاج عن الخدمات المقدمة (التغذية) باللغة العربية ولغة الحجاج، ورفع نتائج الاستبيان ضمن التقرير النهائي.","التعهد والالتزام بتقديم التقرير المفصل بتنفيذ الأعمال بعد نهاية الموسم، بموعد أقصاه {{report_due_date}}."]},{"id":"p7","type":"divider"},{"id":"p8","type":"fields","style":"grid","columns":2,"keys":["rep_name","pledge_date"]},{"id":"p9","type":"signature","slots":[{"label":"التوقيع","key":"signature"},{"label":"الختم","key":"stamp"}]},{"id":"p10","type":"note","text":"جميع النقاط المذكورة في ملحق العقد قد يتم تحديثها عن طريق تعاميم، وذلك بحسب حاجة العمل."}],"fields":{"company_name":{"label":"اسم الشركة","type":"text","source":"company.name","readonly":true},"caterer_name":{"label":"اسم المتعهد","type":"text","source":"caterer.name","readonly":true},"hijri_year":{"label":"السنة","type":"text","source":"hijri_year","readonly":true},"contract_number":{"label":"رقم العقد","type":"text","owner":"admin","required":true},"plan_due_date":{"label":"موعد الخطة التشغيلية","type":"date","owner":"admin"},"training_due_date":{"label":"موعد شهادات تدريب الكيروسين","type":"date","owner":"admin"},"report_due_date":{"label":"موعد التقرير الختامي","type":"date","owner":"admin"},"rep_name":{"label":"ممثل المنشأة","type":"text","source":"caterer.owner_name","owner":"caterer","required":true},"pledge_date":{"label":"التاريخ","type":"date","owner":"caterer","required":true}}}'::jsonb, true, false, true, true, now()),
  ('liaison_officer', 'تعيين ضابط اتصال', 'يطلب من المتعهد تسمية ضابط اتصال يكون المسؤول المباشر عن استلام الملاحظات والتنسيق اليومي.', 'تشغيلي',
   '{"blocks":[{"id":"b1","type":"paragraph","text":"السادة/ لجنة التغذية بشركة {{company_name}}"},{"id":"b2","type":"paragraph","text":"نحن إدارة مطبخ: {{kitchen_name}}   سجل تجاري رقم: {{cr_number}}"},{"id":"b3","type":"paragraph","text":"تحية طيبة وبعد،،"},{"id":"b4","type":"paragraph","text":"بالإشارة إلى التعاون القائم بين شركة {{company_name}} ومطبخكم الموقر في تقديم خدمات الإعاشة، ومن مبدأ تنظيم العمل وضمان سرعة الاستجابة والتنسيق الفعّال في تنفيذ المهام اليومية؛"},{"id":"b5","type":"paragraph","text":"نرجو منكم التكرم بتزويدنا ببيانات ضابط اتصال من طرفكم، ليكون هو المسؤول المباشر عن استلام الملاحظات والتنسيق مع فريق عملنا، مع تزويدنا ببيانات التواصل الخاصة به كما هو موضح أدناه:"},{"id":"b6","type":"fields","style":"list","keys":["officer_name","officer_phone","officer_email"]},{"id":"b7","type":"paragraph","text":"بناءً عليه، يرجى اعتماد التواصل مع المذكور أعلاه في كل ما يتعلق بمتطلبات الإعاشة اليومية، الجداول الزمنية، وملاحظات التشغيل."},{"id":"b8","type":"paragraph","text":"شاكرين لكم تعاونكم الدائم،،"},{"id":"b9","type":"signature","slots":[{"label":"التوقيع","key":"signature"},{"label":"الختم","key":"stamp"}]}],"fields":{"company_name":{"label":"اسم الشركة","type":"text","source":"company.name","readonly":true},"kitchen_name":{"label":"اسم المطبخ","type":"text","source":"caterer.name","readonly":true},"cr_number":{"label":"السجل التجاري","type":"text","source":"caterer.cr_number","readonly":true},"officer_name":{"label":"اسم ضابط الاتصال","type":"text","owner":"caterer","source":"caterer.liaison_name","required":true},"officer_phone":{"label":"رقم الجوال","type":"phone","owner":"caterer","source":"caterer.liaison_phone","required":true},"officer_email":{"label":"البريد الإلكتروني","type":"email","owner":"caterer","source":"caterer.email"}}}'::jsonb, true, false, true, true, now()),
  ('readiness_minutes_mina', 'محضر تأكيد جاهزية تقديم خدمة الإعاشة (منى)', 'نموذج الوزارة بتصميمه الأصلي. يوقّعه ممثل شركة تقديم الخدمة وممثل مزود الإعاشة، ويثبت جاهزية مواقع الإعاشة بمشعر منى بنداً بنداً.', 'تشغيلي',
   '{"chrome":"none","scope":"center","blocks":[{"id":"sheet","type":"grid","widths":["17%","41%","21%","21%"],"rows":[{"cells":[{"span":4,"tone":"label","align":"center","lines":["محضر تأكيد جاهزية تقديم خدمة الإعاشة","بين شركة تقديم الخدمة","ومزود خدمة الإعاشة","لموسم حج عام {{hijri_year}}هـ"]}]},{"cells":[{"text":"اليوم","tone":"label"},{"field":"minute_weekday"},{"text":"التاريخ","tone":"label"},{"field":"minute_date"}]},{"cells":[{"text":"بيانات المشعر","tone":"label","span":4,"align":"center"}]},{"cells":[{"text":"اسم المشعر","tone":"label","rowspan":2},{"text":"منى","tone":"label","align":"center"},{"text":"عرفات","tone":"label","align":"center","span":2}]},{"cells":[{"text":"☑","align":"center"},{"text":"","align":"center","span":2}]},{"cells":[{"text":"بيانات مزود خدمة الإعاشة","tone":"label","span":4,"align":"center"}]},{"cells":[{"text":"رقم السجل التجاري","tone":"label"},{"field":"cr_number"},{"text":"رقم الرخصة","tone":"label"},{"field":"municipal_license"}]},{"cells":[{"text":"رقم التواصل","tone":"label"},{"field":"caterer_phone"},{"text":"اسم المتعهد","tone":"label"},{"field":"caterer_name"}]},{"cells":[{"text":"العنوان الرئيسي","tone":"label"},{"field":"caterer_address","span":3}]},{"cells":[{"text":"بيانات شركة تقديم الخدمة","tone":"label","span":4,"align":"center"}]},{"cells":[{"text":"رقم الترخيص","tone":"label"},{"field":"facility_license"},{"text":"اسم المنشأة","tone":"label"},{"field":"facility_name"}]},{"cells":[{"text":"رقم المربع","tone":"label"},{"field":"murabba"},{"text":"رقم مركز الضيافة","tone":"label"},{"field":"center_code"}]},{"cells":[{"text":"رقم الشاخص","tone":"label"},{"field":"shakhis"},{"text":"عدد الحجاج","tone":"label"},{"field":"pilgrims_count"}]},{"cells":[{"text":"اسم رئيس المركز","tone":"label"},{"field":"center_head_name"},{"text":"رقم التواصل","tone":"label"},{"field":"center_head_phone"}]},{"cells":[{"text":"جاهزية مواقع الإعاشة","tone":"label","span":4,"align":"center"}]},{"cells":[{"text":"م","tone":"label"},{"text":